#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  Шагов: %s%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  В браузере действуете вы; мастер говорит, что сделать, и принимает\n' "$DIM"
  printf '  скопированные значения. Остановить можно в любой момент (Ctrl-C):\n'
  printf '  при повторном запуске готовые шаги пропускаются.%s\n' "$RESET"
  pause "Начать? Нажмите Enter"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Шаг %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ открываю%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "не удалось открыть браузер, откройте вручную: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Нажмите Enter, чтобы продолжить}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter — оставить текущее]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter — оставить текущее]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Готово%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "осталось сделать вручную:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up what a signed, notarized Lumilo release needs on this Mac:
# a Developer ID Application certificate, notarization credentials from an
# App Store Connect API key (keychain profile "lumilo-notary"), and the key
# pair that signs Lumilo's own updates. Nothing secret is written to the
# repository; secrets stay in the login Keychain.

TEAM_ID="${TEAM_ID:-88VB25X5UW}"
PROFILE="lumilo-notary"
KEY_DIR="$HOME/.appstoreconnect/private_keys"
REPO="$(cd "$(dirname "$0")/.." && pwd)"

run_wizard() {

TOTAL_STAGES=4

banner "Lumilo: подпись релизов"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Сертификат Developer ID Application"
if security find-identity -v -p codesigning | grep -q "Developer ID Application:.*($TEAM_ID)"; then
  say "Сертификат Developer ID Application команды $TEAM_ID уже в связке ключей."
else
  say "Создайте сертификат, которым подписываются приложения не из App Store."
  step "Откроется Xcode. Откройте Xcode → Settings… → Accounts."
  step "Выберите свой Apple ID, затем команду с ID $TEAM_ID."
  step "Нажмите Manage Certificates…, затем + → Developer ID Application."
  note "Создать его может только Account Holder команды."
  open -a Xcode || true
  until security find-identity -v -p codesigning | grep -q "Developer ID Application:.*($TEAM_ID)"; do
    pause "Нажмите Enter, когда сертификат будет создан"
    security find-identity -v -p codesigning | grep -q "Developer ID Application:.*($TEAM_ID)" ||
      warn "В связке ключей его пока нет."
  done
fi
IDENTITY=$(security find-identity -v -p codesigning | grep -o "\"Developer ID Application:.*($TEAM_ID)\"" | head -n1 | tr -d '"')
printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$IDENTITY"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Ключ App Store Connect API"
if xcrun notarytool history --keychain-profile "$PROFILE" >/dev/null 2>&1; then
  say "Профиль нотаризации \"$PROFILE\" уже работает; ключ API не нужен."
  SKIP_KEY=1
else
  SKIP_KEY=0
  say "Для нотаризации нужен ключ App Store Connect API."
  open_url "https://appstoreconnect.apple.com/access/integrations/api"
  step "Откройте Users and Access → Integrations → App Store Connect API → Team Keys."
  step "Нажмите + (Generate API Key). Name: Lumilo notarization. Access: Developer."
  step "Нажмите Download у нового ключа. Скачать его можно только один раз: AuthKey_<KEY ID>.p8."
  step "Скопируйте Issuer ID над таблицей ключей и Key ID нового ключа."
  ask ASC_ISSUER_ID "Issuer ID:"
  ask ASC_KEY_ID "Key ID:"
  P8="$HOME/Downloads/AuthKey_${ASC_KEY_ID}.p8"
  while [[ ! -f "$P8" ]]; do
    warn "Файл не найден: $P8"
    ask P8 "Путь к скачанному файлу .p8:"
    P8="${P8/#\~/$HOME}"
  done
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Доступ для нотаризации"
if [[ "$SKIP_KEY" == 1 ]]; then
  say "Профиль \"$PROFILE\" готов."
else
  say "Ключ переносится в $KEY_DIR (права 600), а notarytool сохраняет профиль в связке ключей."
  mkdir -p "$KEY_DIR" && chmod 700 "$KEY_DIR"
  mv -n "$P8" "$KEY_DIR/" && chmod 600 "$KEY_DIR/AuthKey_${ASC_KEY_ID}.p8"
  xcrun notarytool store-credentials "$PROFILE" \
    --key "$KEY_DIR/AuthKey_${ASC_KEY_ID}.p8" --key-id "$ASC_KEY_ID" --issuer "$ASC_ISSUER_ID"
  if xcrun notarytool history --keychain-profile "$PROFILE" >/dev/null; then
    printf '  %s✓%s Apple принял ключ (профиль %s)\n' "$GREEN" "$RESET" "$PROFILE"
  else
    warn "notarytool не смог войти с этим ключом; проверьте Key ID, Issuer ID и доступ ключа."
    exit 1
  fi
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Ключ подписи обновлений"
if security find-generic-password -a "$USER" -s "Lumilo update key" >/dev/null 2>&1; then
  say "«Lumilo update key» уже в связке ключей; оставляю его (с новым ключом установленные копии не обновятся)."
else
  say "Создаю пару ключей для подписи обновлений Lumilo. Установленные копии принимают только обновления, подписанные этим ключом."
  OUT="$HOME/.config/lumilo/update-keys"
  mkdir -p "$OUT" && chmod 700 "$OUT"
  (cd "$REPO" && go tool mygo keygen -o "$OUT")
  KEY_FILE="$OUT/mygo-update.key"
  [[ -f "$KEY_FILE" ]] || { warn "keygen не создал $KEY_FILE"; exit 1; }
  chmod 600 "$KEY_FILE"
  security add-generic-password -a "$USER" -s "Lumilo update key" -U -w "$(cat "$KEY_FILE")"
  [[ "$(security find-generic-password -a "$USER" -s "Lumilo update key" -w)" == "$(cat "$KEY_FILE")" ]] ||
    { warn "Копия в связке ключей отличается от файла; остановка."; exit 1; }
  printf '  %s✓%s Секретный ключ сохранён в связке ключей как «Lumilo update key»\n' "$GREEN" "$RESET"
  note "Сохраните $KEY_FILE и в менеджере паролей: без него установленные копии не обновятся."
  note "Открытый ключ: $OUT/mygo-update.pub (он пойдёт в mygo.json)."
fi
pause

finish
note "Сертификат подписи: $IDENTITY"
note "Профиль нотаризации: $PROFILE"
}

run_wizard "$@"; exit
